// Расписание встреч на день: пересечения, свободные окна, загрузка людей (перенос schedule.py).
const DAY_START = "09:00";
const DAY_END = "19:00";

const MEETINGS = [
  ["Планёрка", "09:30-10:00", ["Оля", "Пётр", "Сева", "Таня"]],
  ["Созвон с клиентом", "10:15-11:00", ["Оля", "Сева"]],
  ["Ревью дизайна", "10:45-11:30", ["Таня", "Пётр"]],
  ["Обед с партнёром", "13:00-14:15", ["Оля"]],
  ["Собеседование", "14:00-15:00", ["Пётр", "Таня"]],
  ["Разбор задач", "15:30-16:30", ["Сева", "Таня", "Пётр"]],
  ["Звонок поставщику", "16:00-16:20", ["Оля"]],
  ["Итоги дня", "18:00-18:30", ["Оля", "Пётр", "Сева", "Таня"]],
];

const toMin = (hhmm) => {
  const [h, m] = hhmm.split(":");
  return Number(h) * 60 + Number(m);
};
const two = (n) => String(n).padStart(2, "0");
const toHhmm = (minutes) => `${two(Math.floor(minutes / 60))}:${two(minutes % 60)}`;
const parse = (span) => span.split("-").map(toMin);
const cmpPair = (x, y) => x[0] - y[0] || x[1] - y[1];

function durationText(minutes) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  if (h && m) return `${h} ч ${m} мин`;
  if (h) return `${h} ч`;
  return `${m} мин`;
}

function people(meetings) {
  const names = [];
  for (const [, , who] of meetings) for (const name of who) if (!names.includes(name)) names.push(name);
  return names.sort();
}

function overlaps(meetings) {
  const out = [];
  for (let i = 0; i < meetings.length; i++) {
    for (let j = i + 1; j < meetings.length; j++) {
      const [a1, b1] = parse(meetings[i][1]);
      const [a2, b2] = parse(meetings[j][1]);
      const start = Math.max(a1, a2);
      const end = Math.min(b1, b2);
      if (start < end) {
        const common = meetings[i][2].filter((n) => meetings[j][2].includes(n)).sort();
        out.push([meetings[i][0], meetings[j][0], end - start, common]);
      }
    }
  }
  return out;
}

function merge(spans) {
  const merged = [];
  for (const [a, b] of spans) {
    const last = merged[merged.length - 1];
    if (last && a <= last[1]) last[1] = Math.max(last[1], b);
    else merged.push([a, b]);
  }
  return merged;
}

const busyIntervals = (meetings, name) =>
  merge(meetings.filter(([, , who]) => who.includes(name)).map(([, span]) => parse(span)).sort(cmpPair));

function freeWindows(busy, minLen = 30) {
  const end = toMin(DAY_END);
  const out = [];
  let cur = toMin(DAY_START);
  for (const [a, b] of busy) {
    if (a - cur >= minLen) out.push([cur, a]);
    cur = Math.max(cur, b);
  }
  if (end - cur >= minLen) out.push([cur, end]);
  return out;
}

const commonFree = (meetings, minLen = 30) =>
  freeWindows(merge(meetings.map(([, span]) => parse(span)).sort(cmpPair)), minLen);

function printList(meetings) {
  console.log("Встречи:");
  for (const [title, span, who] of [...meetings].sort((x, y) => cmpPair(parse(x[1]), parse(y[1])))) {
    const [a, b] = parse(span);
    console.log(`  ${toHhmm(a)}–${toHhmm(b)}  ${title.padEnd(20)} ${durationText(b - a).padStart(10)}  (${who.length} чел.)`);
  }
}

function printOverlaps(meetings) {
  console.log("Пересечения:");
  const found = overlaps(meetings);
  if (!found.length) console.log("  нет");
  for (const [m1, m2, minutes, common] of found) {
    const clash = common.length ? `, конфликт у: ${common.join(", ")}` : "";
    console.log(`  «${m1}» и «${m2}» — ${minutes} мин${clash}`);
  }
}

function printPeople(meetings) {
  console.log("Загрузка:");
  const day = toMin(DAY_END) - toMin(DAY_START);
  for (const name of people(meetings)) {
    const busy = busyIntervals(meetings, name);
    const total = busy.reduce((n, [a, b]) => n + b - a, 0);
    const share = (total * 100) / day;
    const windows = freeWindows(busy, 60);
    const longest = Math.max(0, ...windows.map(([a, b]) => b - a));
    console.log(
      `  ${name.padEnd(5)} занят ${durationText(total).padStart(10)} (${share.toFixed(1).padStart(4)}%), окон от часа: ${windows.length}, самое длинное ${durationText(longest)}`,
    );
  }
}

function printCommon(meetings) {
  console.log("Окна, свободные у всех (от 30 мин):");
  for (const [a, b] of commonFree(meetings)) console.log(`  ${toHhmm(a)}–${toHhmm(b)} (${durationText(b - a)})`);
}

console.log(`РАСПИСАНИЕ НА ДЕНЬ (${DAY_START}–${DAY_END})`);
console.log();
printList(MEETINGS);
console.log();
printOverlaps(MEETINGS);
console.log();
printPeople(MEETINGS);
console.log();
printCommon(MEETINGS);
